# Estimator variants for B (3-view CV): exclude pewees from group means; trimmed means (drop extreme members along current margin). Record spatial pilot in notes.
def fit_dir_var(Xtr_list, gtr, idx_tr, variant):
    Xtr = np.concatenate(Xtr_list); gg = np.concatenate([gtr]*len(Xtr_list)); ii = np.concatenate([idx_tr]*len(Xtr_list))
    keep = np.ones(len(Xtr), bool)
    if variant=='nopewee': keep &= ~np.isin(ii, pew)
    if variant=='noquirk': keep &= ~np.isin(ii, np.r_[pew, tow, mea])
    mu = np.array([Xtr[keep&(gg==k)].mean(0) for k in range(4)])
    if variant.startswith('trim'):
        frac = float(variant[4:])
        D = ((mu[1]-mu[0])+(mu[3]-mu[2]))/2; B = ((mu[2]-mu[0])+(mu[3]-mu[1]))/2; w = B-(B@D)/(D@D)*D
        s = Xtr@w
        for k in range(4):
            sel = np.where(gg==k)[0]; lo, hi = np.quantile(s[sel], [frac, 1-frac]); keep[sel[(s[sel]<lo)|(s[sel]>hi)]] = False
        mu = np.array([Xtr[keep&(gg==k)].mean(0) for k in range(4)])
    D = ((mu[1]-mu[0])+(mu[3]-mu[2]))/2; B = ((mu[2]-mu[0])+(mu[3]-mu[1]))/2
    v = D-(D@B)/(B@B)*B; v = v/(v@D)
    w = B-(B@D)/(D@D)*D; w = w*16/(w@B)
    mL = (mu[0]+mu[1])/2@w; mW = (mu[2]+mu[3])/2@w
    return w, -(mL+mW)/2, (d0@D)*v, mu.mean(0)
